}

/* ---------- ABOUT ---------- */
.about-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 18px;
  color: var(--color-text-muted);
}

/* ---------- PROJECTS GRID (CSS Grid) ---------- */
.projects-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px;
}

.project-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.project-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 16px 32px rgba(23, 24, 43, 0.12);
}

.project-card--featured {
  grid-column: span 2;
}

.project-card__media {
  height: 150px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.project-card__media--one   { background: linear-gradient(135deg, #4361ee, #7209b7); }
.project-card__media--two   { background: linear-gradient(135deg, #06b6d4, #4361ee); }
.project-card__media--three { background: linear-gradient(135deg, #f72585, #7209b7); }
.project-card__media--four  { background: linear-gradient(135deg, #4cc9f0, #4361ee); }
.project-card__media--five  { background: linear-gradient(135deg, #7209b7, #4361ee); }

.project-card__body {
  padding: 18px 20px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.project-card__body h3 {
  font-size: 1.1rem;
  margin-bottom: 8px;
}

.project-card__body p {
  color: var(--color-text-muted);
  font-size: 0.95rem;
  flex: 1;
}

.tag-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}

.tag {
  background-color: var(--color-bg-alt);
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
}

/* ---------- SKILLS (Flexbox) ---------- */
.skills-row {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  justify-content: center;
}

.skill-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 20px;
  flex: 1 1 200px;
  max-width: 240px;
  text-align: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.skill-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 24px rgba(23, 24, 43, 0.08);
}

.skill-card h3 {
  color: var(--color-primary);
  font-size: 1.05rem;
  margin-bottom: 6px;
}

.skill-card p {
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

/* ---------- CONTACT ---------- */
.contact-intro {
  color: var(--color-text-muted);
  margin-bottom: 20px;
}

.contact-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.contact-list li {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 10px;
  padding: 14px 18px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: baseline;
}

.contact-label {
  font-weight: 700;
  min-width: 80px;
}

.contact-list a {
  text-decoration: none;
  font-weight: 600;
}

.contact-list a:hover,
.contact-list a:focus {
  text-decoration: underline;
}

/* ---------- FOOTER ---------- */
.site-footer {
  text-align: center;
  padding: 24px 16px;
  background-color: var(--color-dark);
  color: #c7d3ff;
  font-size: 0.9rem;
}

/* ---------- RESPONSIVE (mobile-first: nav-toggle shown by default above) ---------- */
@media (min-width: 768px) {
  .nav-toggle {
    display: none;
  }

  .primary-nav {
    order: 0;
    width: auto;
    max-height: none;
    overflow: visible;
  }

  .primary-nav ul {
    flex-direction: row;
    gap: 22px;
    padding-top: 0;
  }

  .primary-nav a {
    padding: 4px 2px;
  }

  .hero h1 {
    font-size: 2.6rem;
  }

  .about-content {
    grid-template-columns: 1fr 1fr;
  }
}

@media (min-width: 1024px) {
  .hero {
    padding: 80px 20px;
  }

  .hero h1 {
    font-size: 3rem;
  }
}

/* ---------- ACCESSIBILITY: reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

// Responsive Portfolio Layout — mobile navigation toggle
// Opens/closes the primary nav on small screens and keeps the
// hamburger button's ARIA state in sync for screen readers.

document.addEventListener("DOMContentLoaded", () => {
  const navToggle = document.getElementById("navToggle");
  const primaryNav = document.getElementById("primaryNav");

  if (!navToggle || !primaryNav) return;

  const closeNav = () => {
    primaryNav.classList.remove("is-open");
    navToggle.setAttribute("aria-expanded", "false");
  };

  const toggleNav = () => {
    const isOpen = primaryNav.classList.toggle("is-open");
    navToggle.setAttribute("aria-expanded", String(isOpen));
  };

  navToggle.addEventListener("click", toggleNav);

  // Close the menu after a link is tapped, and when the viewport
  // grows past the mobile breakpoint the CSS already handles.
  primaryNav.querySelectorAll("a").forEach((link) => {
    link.addEventListener("click", () => {
      if (window.matchMedia("(max-width: 767px)").matches) {
        closeNav();
      }
    });
  });

  window.addEventListener("resize", () => {
    if (window.matchMedia("(min-width: 768px)").matches) {
      closeNav();
    }
  });
});

