/* ==========================================================================
   Aurora Buds — Product Showcase Site
   ========================================================================== */

:root {
  --color-bg: #f7f8fc;
  --color-bg-alt: #eef1fa;
  --color-surface: #ffffff;
  --color-text: #17182b;
  --color-text-muted: #565b73;
  --color-primary: #7209b7;
  --color-primary-dark: #560a8a;
  --color-dark: #17182b;
  --color-accent: #f72585;
  --color-border: #dde3f0;
  --color-star: #f7b500;
  --radius: 14px;
  --max-width: 1100px;

  --swatch-violet: #7209b7;
  --swatch-cyan: #06b6d4;
  --swatch-coral: #f72585;
  --swatch-slate: #4b5563;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: "Segoe UI", Roboto, Arial, sans-serif;
  line-height: 1.65;
  color: var(--color-text);
  background-color: var(--color-bg);
}

img, svg {
  max-width: 100%;
  height: auto;
  display: block;
}

ul {
  list-style: none;
}

a {
  color: var(--color-primary);
}

h1, h2, h3 {
  color: var(--color-dark);
  line-height: 1.2;
}

button {
  font: inherit;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.section {
  padding: 48px 20px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-alt {
  background-color: var(--color-bg-alt);
  max-width: none;
}

.section-alt > * {
  max-width: var(--max-width);
  margin-left: auto;
