  background: var(--panel);
  color: var(--text);
  font-size: 1rem;
}

#city-input:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

#search-btn,
#location-btn {
  padding: 0.65rem 1.1rem;
  border-radius: 8px;
  border: none;
  background: var(--accent);
  color: #08122a;
  font-weight: 600;
  cursor: pointer;
}

#location-btn {
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
}

#search-btn:hover,
#location-btn:hover {
  filter: brightness(1.08);
}

.suggestions {
  list-style: none;
  margin: 0.3rem 0 0;
  padding: 0;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
}

.suggestions li {
  padding: 0.6rem 0.9rem;
  cursor: pointer;
  color: var(--text);
  border-bottom: 1px solid var(--border);
}

.suggestions li:last-child {
  border-bottom: none;
}

.suggestions li:hover,
.suggestions li.highlighted {
  background: var(--panel-2);
}

.suggestions .suggestion-region {
  color: var(--muted);
  font-size: 0.85rem;
}

.status-msg {
  min-height: 1.3em;
  color: var(--muted);
  margin: 0.75rem 0;
}

.status-msg.error {
  color: var(--danger);
}

.dashboard {
  margin-top: 1rem;
}

.current-card {
  display: flex;
  gap: 1.25rem;
  align-items: center;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.25rem 1.5rem;
  flex-wrap: wrap;
}

.current-main {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.current-icon {
  font-size: 3rem;
  line-height: 1;
}

.current-temp {
  font-size: 3rem;
  font-weight: 700;
}

.current-details h2 {
  margin: 0 0 0.15rem;
  font-size: 1.3rem;
}

.current-details p {
  margin: 0 0 0.5rem;
  color: var(--muted);
}

.stat-row {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  font-size: 0.9rem;
  color: var(--muted);
}

.stat-row strong {
  color: var(--text);
}

.updated-at {
  margin-top: 0.5rem !important;
  font-size: 0.75rem !important;
  color: var(--muted);
}

.unit-toggle {
  margin: 0.75rem 0;
  text-align: right;
}

.ghost-btn {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--muted);
  padding: 0.4rem 0.9rem;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.85rem;
}

.ghost-btn:hover {
  color: var(--text);
  border-color: var(--accent);
}

h3 {
  margin: 1.5rem 0 0.75rem;
  font-size: 1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
